import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/core/utils/money.dart';import 'package:pos_app/features/reports/data/csv_export_service.dart';import 'package:pos_app/features/reports/data/report_repository.dart';class ReportsScreen extends StatelessWidget{const ReportsScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Reportes')),body:FutureBuilder(future:ReportRepository(appDatabase).today(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final m=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[ListTile(title:const Text('Ventas hoy'),trailing:Text(formatMoney(m.salesCents))),ListTile(title:const Text('Costo FIFO'),trailing:Text(formatMoney(m.fifoCostCents))),ListTile(title:const Text('Utilidad bruta'),trailing:Text(formatMoney(m.grossProfitCents))),ListTile(title:const Text('Gastos'),trailing:Text(formatMoney(m.expensesCents))),ListTile(title:const Text('Resultado'),trailing:Text(formatMoney(m.resultCents))),FilledButton(onPressed:()async{final f=await CsvExportService(appDatabase).sales();if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('CSV: ${f.path}')));},child:const Text('Exportar ventas CSV'))]);}));}
